 r['items']=[i for i in r['items'] if i['url'].split('?')[0] not in ['tunnel-neuropathies.html','stress-fractures.html']]
 if r['id'] in ['shoulder','elbow','wrist','hand','hip','knee','foot','ankle','upper-limb','lower-limb']:
  for module,title,desc in [('tunnel-neuropathies','Туннельные невропатии','13 локализаций · нервы · карта денервации · причины компрессии'),('stress-fractures','Стрессовые и недостаточностные переломы','Стресс-реакция · опасные зоны · SIFK · крестец · Fredericson')]:
   if module=='stress-fractures' and r['id'] in ['shoulder','elbow','wrist','hand','upper-limb']:continue
   r['items'].append(dict(title=title,description=desc,url=f'{module}.html?from={r["id"]}',type='КЛИНИЧЕСКИЙ МОДУЛЬ',thumb='module231/'+module+'.svg'))
 if r['id']=='spine':r['items'].append(dict(title='Стрессовые и недостаточностные переломы',description='Крестец · тазовое кольцо · компрессионные переломы',url='stress-fractures.html?from=spine',type='КЛИНИЧЕСКИЙ МОДУЛЬ',thumb='module231/stress-fractures.svg'))
